def bfs(capacity, flow, adj, r, s, t):
    visited = [False] * r
    parent = [-1] * r
    visited[s] = True
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited[v] and capacity[u][v] - flow[u][v] > 0:
                visited[v] = True
                parent[v] = u
                if v == t:
                    return parent
                queue.append(v)
    return parent

def dinic(capacity, flow, adj, r, s, t):
    flow_ = [0]

    def dfs(u, pushed):
        if pushed == 0 or u == t:
            return pushed
        for v in adj[u]:
            if capacity[u][v] - flow[u][v] > 0:
                tr = dfs(v, min(pushed, capacity[u][v] - flow[u][v]))
                if tr > 0:
                    flow[u][v] += tr
                    flow[v][u] -= tr
                    return tr
        return 0

    while True:
        parent = bfs(capacity, flow, adj, r, s, t)
        if parent[-1] == -1:
            break
        while True:
            pushed = dfs(s, float('inf'))
            if pushed == 0:
                break
            flow_[0] += pushed

    return flow_[0], flow

class Solution:
    def solve(self, n, m, a, b, edges):
        # First check if sums are equal
        if sum(a) != sum(b):
            return False, None

        # Create flow network
        # Source = 0, Sink = 2*n + 1, Cities = 1 to n
        S = 0
        T = 2 * n + 1
        r = 2 * n + 2

        capacity = defaultdict(lambda: defaultdict(int))
        adj = defaultdict(list)

        # Source to cities: capacity = ai
        for i in range(n):
            city = i + 1
            capacity[S][city] = a[i]
            adj[S].append(city)
            adj[city].append(S)

        # Cities to sink: capacity = bi
        for i in range(n):
            city = i + 1
            capacity[city][T] = b[i]
            adj[city].append(T)
            adj[T].append(city)

        # City to adjacent city: capacity = inf (or any large value)
        INF = 10**9
        for p, q in edges:
            cap1 = p
            cap2 = q
            # City p can send to city q
            capacity[cap1][cap2] = INF
            adj[cap1].append(cap2)
            adj[cap2].append(cap1)
            # City q can send to city p
            capacity[cap2][cap1] = INF
            adj[cap2].append(cap1)
            adj[cap1].append(cap2)

        # Add self-loops (stay in same city)
        for i in range(n):
            city = i + 1
            capacity[city][city] = INF
            adj[city].append(city)

        # Run max flow
        flow_matrix = defaultdict(lambda: defaultdict(int))
        max_flow, flow_val = dinic(
            lambda u,v: capacity[u][v],
            flow_matrix,
            adj,
            r,
            S,
            T
        )

        if max_flow != sum(a):
            return False, None

        # Build result matrix
        res = [[0] * n for _ in range(n)]

        # For each city, how many soldiers move to each target city
        # We need to reconstruct the flow from city i to city j
        # Flow from city (i+1) to city (j+1)
        for i in range(n):
            for j in range(n):
                if (i + 1) == (j + 1):
                    res[i][j] = flow_matrix[i + 1][j + 1]
                else:
                    res[i][j] = flow_matrix[i + 1][j + 1]

        return True, res

