            r_from_top = r - 1
            c_from_left = c - 1

            if r_from_top >= 0 and dp[r_from_top][c] != INF:
                best_prev = min(best_prev, dp[r_from_top][c])
            if c_from_left >= 0 and dp[r][c_from_left] != INF:
                best_prev = min(best_prev, dp[r][c_from_left])

            if best_prev == INF:
                continue

            # Check collisions at this position at time = time_val
            collision_energy = 0
            for (tx, ty, d_val, t_start, energy) in transformers:
                if time_val < t_start:
                    continue

                steps = time_val - t_start
                base = steps // 4
                cycle = steps % 4

                if cycle == 0:
                    p_row, p_col = tx, ty
                elif cycle == 1:
                    p_row, p_col = tx + d_val, ty - d_val
                elif cycle == 2:
                    p_row, p_col = tx + d_val, ty
                elif cycle == 3:
                    p_row, p_col = tx, ty + d_val

                if p_row == r and p_col == c:
                    collision_energy += energy

            dp[r][c] = best_prev + collision_energy

    return HackyResult(dp[N-1][M-1])

