def solve_t_packing(n: int, m: int) -> str:
    # T-shape orientations (4 cells each):
    # Orientation 0: down T (### on top, .#. stem - wait, no)
    # Let's define them based on the ASCII patterns given:
    # 4 orientations of T-shape (4 cells each)
    T_SHAPES = [
        # [[0,0],[0,1],[0,2],[1,1]] - down T
        [(0, 0), (0, 1), (0, 2), (1, 1)],
        # [[0,2],[1,0],[1,1],[1,2]] - up T  
        [(0, 2), (1, 0), (1, 1), (1, 2)],
        # [[0,1],[1,0],[1,1],[1,2]] - left T
        [(0, 1), (1, 0), (1, 1), (1, 2)],
        # [[0,0],[1,1],[2,0],[2,1]] - right T (need to verify)
        [(0, 1), (1, 0), (1, 1), (2, 1)],  # spot check
    ]

    grid = [['.' * m for _ in range(n)]]  # placeholder

    def check_shape(r, c, shape):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m):
                return False
            if grid[nr][nc] != '.':
                return False
        return True

    def apply_shape(r, c, shape, letter):
        for i in range(n):
            grid[i] = list(grid[i])
        for dr, dc in shape:
            grid[r + dr][c + dc] = letter

    def remove_shape(r, c, shape):
        for dr, dc in shape:
            grid[r + dr][c + dc] = '.'

    best = [0]
    best_pos = None
    count = [0]

    def backtrack(idx, current):
        if len(current) > best[0]:
            best[0] = len(current)
            best_pos = [row[:] for row in grid]

        if idx == n * m and len(current) > 0:
            return

        start_r = idx // m
        start_c = idx % m

        for shape in T_SHAPES:
            if check_shape(start_r, start_c, shape):
                count[0] = len(current)
                letter = chr(ord('A') + count[0] - len(current)) if count[0] > 0 else ''

                # Try placing
                for dr, dc in shape:
                    pos = (start_r + dr, start_c + dc)
                    current[pos] = current.get(pos, '.') + letter if letter else current.get(pos, '.')

                apply_shape(start_r, start_c, shape, current.get((start_r, start_c), '.'))

                backtrack(idx + 1, current.copy())

                remove_shape(start_r, start_c, shape)

    # Use proper backtracking
    grid_char = [['.' for _ in range(m)] for _ in range(n)]

    def search(idx):
        if idx > len(T_SHAPES):
            return

        count_map = {}
        letter = ord('A')
        shape_count = 0

        def can_place(r, c, shape):
            for dr, dc in shape:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < n and 0 <= nc < m):
                    return False
                if grid_char[nr][nc] != '.':
                    return False
            return True

        def mark(r, c, shape, letter_char):
            for dr, dc in shape:
                grid_char[r + dr][c + dc] = letter_char

        def unmark(r, c, shape, letter_char):
            for dr, dc in shape:
                grid_char[r + dr][c + dc] = '.'

        best_count = [0]

        def place(idx):
            if idx == n * m and shape_count > 0:
                if shape_count > best_count[0]:
                    best_count[0] = shape_count
                return

            r, c = idx // m, idx % m

            for shape_idx, shape in enumerate(T_SHAPES):
                if can_place(r, c, shape):
                    mark(r, c, shape, chr(ord('A') + shape_idx))
                    shape_count += 1
                    place(idx + 1)
                    shape_count -= 1
                    unmark(r, c, shape, chr(ord('A') + shape_idx))

        place(0)
        return best_count[0], grid_char

    max_count, result_grid = search(0)

    output = []
    for row in result_grid:
        output.append(''.join(row))

    return f"{max_count}\n" + '\n'.join(output)

