def is_prime(n):
    """Check if n is prime using trial division."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(num):
    """Return a set of prime factors of num."""
    if num <= 1:
        return set()
    factors = set()

    if num % 2 == 0:
        factors.add(2)
        while num % 2 == 0:
            num //= 2

    i = 3
    while i * i <= num:
        if num % i == 0:
            factors.add(i)
            while num % i == 0:
                num //= i
        i += 2

    if num > 1:
        factors.add(num)

    return factors

def gcd(a, b):
    """Compute the greatest common divisor of a and b."""
    while b:
        a, b = b, a % b
    return a

def is_primitive_root(b, p):
    """Check if b is a primitive root modulo p."""
    if p <= 2:
        return False

    if gcd(b, p) != 1:
        return False

    phi = p - 1
    for q in prime_factors(phi):
        if pow(b, phi // q, p) == 1:
            return False

    return True

def solve(n, x):
    """
    Find the largest base b (1 < b < x) such that there exists a "Rotatable Number" 
    of length n under base b.

    The key insight is that Rotatable Numbers of length n are related to primes p = n + 1
    where the base b is a primitive root modulo p.
    """
    p = n + 1

    if not is_prime(p):
        return "-1\n"

    # Check bases from x - 1 down to 2 (largest to smallest)
    for b in range(x - 1, 1, -1):
        if gcd(b, p) == 1 and is_primitive_root(b, p):
            return str(b) + "\n"

    return "-1\n"

