    n = int(lines[0])
    points = []
    for i in range(1, n+1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def segments_intersect(a, b, c, d):
        cp1 = cross_product(a, b, c)
        cp2 = cross_product(a, b, d)
        cp3 = cross_product(c, d, a)
        cp4 = cross_product(c, d, b)
        return ((cp1 > 0) ^ (cp2 > 0)) and ((cp3 > 0) ^ (cp4 > 0))

    def triangles_disjoint(t1, t2):
        i1, i2, i3 = t1
        j1, j2, j3 = t2

        if len({i1, i2, i3} & {j1, j2, j3}):
            return False

        for a, b in [(i1, i2), (i2, i3), (i3, i1)]:
            for c, d in [(j1, j2), (j2, j3), (j3, j1)]:
                if segments_intersect(points[a], points[b], points[c], points[d]):
                    return False

        return True

    triangles = []
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                triangles.append((i, j, k))

    result = 0
    for i in range(len(triangles)):
        for j in range(i + 1, len(triangles)):
            if triangles_disjoint(triangles[i], triangles[j]):
                result += 1

    return f"{result}\n"

