def solution(input_str):
    line = input_str.strip().split()
    if len(line) < 3:
        return "0"
    n, k, m = map(int, line)

    # If k = 1, we just choose the starting planet
    if k == 1:
        return str(n)

    # Memoization: (x, cnt, visited_mask)
    memo = {}

    def count_ways(x, cnt, visited):
        state = (x, cnt, visited)
        if state in memo:
            return memo[state]

        if cnt == k:
            return 1

        total = 0
        # Try to visit any unvisited planet y in [1, x + m]
        for y in range(1, min(n, x + m) + 1):
            if not ((visited >> (y - 1)) & 1):
                total = (total + count_ways(y, cnt + 1, visited | (1 << (y - 1)))) % MOD

        memo[state] = total
        return total

    # Sum all paths starting from each planet
    ans = 0
    for start in range(1, n + 1):
        ans = (ans + count_ways(start, 1, 1 << (start - 1))) % MOD

    return str(ans)

