def solution(input_data):
    """
    Count squares in a 0-1 matrix.
    Two types: axis-aligned and diagonal.
    Square must be at least 2x2, have border of 1s, interior of 0s,
    and cannot touch foreign 1s.
    """
    lines = input_data.strip().split('\n')
    idx = 0

    try:
        t = int(lines[idx].strip())
        idx += 1
    except:
        return ""

    results = []

    for _ in range(t):
        try:
            n, m = map(int, lines[idx].split())
            idx += 1

            grid = []
            for i in range(n):
                grid.append(list(lines[idx + i]))
            idx += n

            visited = [[False] * m for _ in range(n)]
            count = 0

            # Process all cells looking for corners of axis-aligned squares
            for r in range(n):
                for c in range(m):
                    if grid[r][c] == '1' and not visited[r][c]:
                        # This '1' could be a corner of an axis-aligned square
                        # Find the minimal bounding box containing this 1 and all connected 1s
                        # Then try to form valid squares

                        # Find the extent of connected region containing (r,c)
                        extent_r = [r, r]
                        extent_c = [c, c]

                        # BFS/DFS to find extent
                        stack = [(r, c)]
                        while stack:
                            yi, yj = stack.pop()
                            extent_r[0] = min(extent_r[0], yi)
                            extent_r[1] = max(extent_r[1], yi)
                            extent_c[0] = min(extent_c[0], yj)
                            extent_c[1] = max(extent_c[1], yj)

                            for dy, dx in [(-1,0), (1,0), (0,-1), (0,1)]:
                                ni, nj = yi + dy, yj + dx
                                if 0 <= ni < n and 0 <= nj < m:
                                    if grid[ni][nj] == '1' and not visited[ni][nj]:
                                        stack.append((ni, nj))

            # Try all possible square sizes from the bounding box
            for top in range(extent_r[0], n):
                for new_c in range(extent_c[0], m):
                    # Find all 4x4 axis-aligned squares that exist
                    for side in range(2, min(n - top + 1, m - new_c + 1)):
                        # Check this position as top-left corner
                        if grid[top][new_c] != '1':
                            continue

                        # Check corners
                        if (grid[top][new_c] != '1' or 
                            grid[top + side - 1][new_c] != '1' or
                            grid[top][new_c + side - 1] != '1' or
                            grid[top + side - 1][new_c + side - 1] != '1'):
                            continue

                        # Check all edges have 1s
                        edge_ok = True
                        # Top edge
                        for j in range(side):
                            if grid[top][new_c + j] != '1':
                                edge_ok = False
                                break
                        if not edge_ok:
                            continue
                        # Bottom edge
                        for j in range(side):
                            if grid[top + side - 1][new_c + j] != '1':
                                edge_ok = False
                                break
                        if not edge_ok:
                            continue
                        # Left edge
                        for i in range(side):
                            if grid[top + i][new_c] != '1':
                                edge_ok = False
                                break
                        if not edge_ok:
                            continue
                        # Right edge
                        for i in range(1, side):
                            if grid[top + i][new_c + side - 1] != '1':
                                edge_ok = False
                                break
                        if not edge_ok:
                            continue

                        # Check interior is all 0s
                        interior_ok = True
                        for i in range(1, side - 1):
                            for j in range(1, side - 1):
                                if grid[top + i][new_c + j] == '1':
                                    interior_ok = False
                                    break
                            if not interior_ok:
                                break
                        if not interior_ok:
                            continue

                        # Check no foreign 1s touch the square (including by corner)
                        # Check 8 neighbors around square
                        touch_ok = True
                        for i in range(-1, side):
                            for j in range(-1, side):
                                # Check cells adjacent to border
                                if grid[top + i][new_c + j] == '1':
                                    # This is a 1 - check if it's part of this square
                                    if not (0 <= top + i < n and 0 <= new_c + j < m):
                                        touch_ok = False
                                        break
                                    # If outside square bounds, it's foreign
                                    if not (top <= top + i < top + side and new_c <= new_c + j < new_c + side):
                                        touch_ok = False
                                        break
                            if not touch_ok:
                                break

                        if touch_ok:
                            # Valid square found
                            count += 1
                            # Mark all cells as visited
                            for i in range(top, top + side):
                                for j in range(new_c, new_c + side):
                                    if 0 <= i < n and 0 <= j < m:
                                        visited[i][j] = True

        except Exception as e:
            continue

        results.append(str(count))

    return '\n'.join(results)


