def solution(input_str):
    MOD = 10**9 + 7

    n_str, k_str = input_str.strip().split()
    n, k = int(n_str), int(k_str)

    # Base case: n=1, beauty is always 0
    if n == 1:
        return "0"

    # Base case: k=1, all characters same, beauty = n-1 always
    if k == 1:
        ans = ((n - 1) * (n - 1)) % MOD
        return str(ans)

    # Handle k >= 2 using dynamic probability
    inv_k = pow(k, MOD - 2, MOD)

    # Precompute powers of inv_k
    inv_pow = [1] * (2 * n + 5)
    for i in range(1, len(inv_pow)):
        inv_pow[i] = (inv_pow[i-1] * inv_k) % MOD

    def get_E_Ii(i):
        """Expected value of indicator I[i]"""
        if 2 * i <= n:
            return inv_pow[n]  # All n positions overlap
        else:
            return inv_pow[i]  # Constraints independent

    def get_E_II(i, j):
        """Expected value of I[i]*I[j] where i < j"""
        if i == j:
            return get_E_Ii(i)
        elif 2 * i > n and 2 * j > n:
            return inv_pow[i + j]  # Independent constraints
        else:
            return inv_pow[n]  # Overlapping constraints

    # E[f²] = Σ E[I[i]] + 2×Σ_{i<j} E[I[i]·I[j]]
    ans = 0

    # Single indicator expectations
    for i in range(1, n):
        ans = (ans + get_E_Ii(i)) % MOD

    # Cross terms
    for i in range(1, n):
        for j in range(i + 1, n):
            ans = (ans + 2 * get_E_II(i, j)) % MOD

    return str(ans)
